BILATERAL=['internal_anal_sphincter_and_smooth_muscle_continuity','external_anal_sphincter_and_each_source_resolved_component','puborectalis_and_anorectal_sling','levator_ani_pubococcygeal_component','levator_ani_iliococcygeal_component','coccygeus_when_obtained_or_reported','ischioanal_fossa_and_fat','obturator_compartment_and_muscle','pelvic_plexus_and_each_actual_autonomic_nerve_route','sacral_or_sciatic_nerve_interface_when_reported','pudendal_nerve_artery_vein_and_each_branch','middle_rectal_artery_and_vein_branches','inferior_rectal_artery_and_vein_branches','ureter_and_urethral_interface_when_present','prostate_seminal_vesicle_or_vas_interface_when_present','vagina_cervix_uterus_or_adnexal_interface_when_present','sacral_pubic_or_hip_interface_when_obtained']
